#!/usr/bin/env python3
"""Apply the approved Delimt landing design and open a website pull request."""
import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
import zlib

PAYLOAD = json.loads(zlib.decompress(base64.b64decode("")))
REPOSITORY = "activist015/delimt"
BRANCH = "website/landing-redesign"
TITLE = "Redesign the landing page around the Android app"


def run(args, cwd, *, capture=False, check=True):
    result = subprocess.run(args, cwd=cwd, text=True,
                            stdout=subprocess.PIPE if capture else None,
                            stderr=subprocess.PIPE if capture else None)
    if check and result.returncode:
        detail = (result.stderr or result.stdout or "").strip() if capture else ""
        raise RuntimeError("Command failed: " + " ".join(args[:4]) + ("\n" + detail if detail else ""))
    return result


def git_blob(data):
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()


def checked_path(checkout, relative):
    path = Path(relative)
    if path.is_absolute() or ".." in path.parts:
        raise RuntimeError("Unsafe update path")
    target = checkout / path
    for parent in (target, *target.parents):
        if parent == checkout.parent:
            break
        if parent.is_symlink():
            raise RuntimeError("A website path is a symbolic link: " + relative)
    if target.exists() and not target.is_file():
        raise RuntimeError("Expected a regular file: " + relative)
    return target


def plan_files(checkout):
    """Check every reviewed baseline before changing any source file."""
    writes = []
    for relative, entry in PAYLOAD.items():
        target = checked_path(checkout, relative)
        current = target.read_bytes() if target.exists() else None
        desired = base64.b64decode(entry["content"], validate=True)
        if current == desired:
            continue
        current_blob = git_blob(current) if current is not None else None
        if current_blob != entry["before"]:
            raise RuntimeError(relative + " has changed since this design was prepared. No update files were changed; ask for an updated installer.")
        writes.append((target, desired))
    return writes


def write_files(writes):
    for target, content in writes:
        target.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(dir=target.parent, delete=False) as stream:
            stream.write(content)
            temporary = Path(stream.name)
        os.replace(temporary, target)


def files_in_ref(root, reference):
    return {path: run(["git", "show", reference + ":" + path], root, capture=True, check=False)
            for path in PAYLOAD}


def main_has_design(root):
    return all(item.returncode == 0 and item.stdout.encode() == base64.b64decode(PAYLOAD[path]["content"])
               for path, item in files_in_ref(root, "origin/main").items())


def common_directory(path):
    return Path(run(["git", "rev-parse", "--path-format=absolute", "--git-common-dir"], path, capture=True).stdout.strip()).resolve()


def prepare_worktree(root):
    checkout = root.parent / "delimt-landing-redesign"
    if checkout.exists():
        actual = Path(run(["git", "rev-parse", "--show-toplevel"], checkout, capture=True).stdout.strip())
        branch = run(["git", "branch", "--show-current"], checkout, capture=True).stdout.strip()
        if actual.resolve() != checkout.resolve() or branch != BRANCH or common_directory(root) != common_directory(checkout):
            raise RuntimeError("The separate design folder contains other work. Nothing was overwritten.")
    else:
        found = run(["git", "show-ref", "--verify", "refs/heads/" + BRANCH], root, capture=True, check=False)
        if found.returncode == 0:
            raise RuntimeError("The design branch already exists without its update folder. It was preserved; ask for help reconnecting the worktree.")
        run(["git", "worktree", "add", "-b", BRANCH, str(checkout), "origin/main"], root)

    changed = run(["git", "diff", "--name-only", "HEAD"], checkout, capture=True).stdout.splitlines()
    untracked = run(["git", "ls-files", "--others", "--exclude-standard"], checkout, capture=True).stdout.splitlines()
    if any(path not in PAYLOAD for path in changed + untracked):
        raise RuntimeError("The design folder contains additional changes. They were preserved; no update files were changed.")
    staged = run(["git", "diff", "--cached", "--name-only"], checkout, capture=True).stdout.splitlines()
    if any(path not in PAYLOAD for path in staged):
        raise RuntimeError("The design folder has unrelated staged files. They were preserved.")
    writes = plan_files(checkout)
    # Refuse a changed main baseline even if resuming an older design branch.
    # The release JSON is deliberately not in PAYLOAD, so future APK metadata
    # can be merged without this updater ever replacing it.
    for relative, item in files_in_ref(root, "origin/main").items():
        desired = base64.b64decode(PAYLOAD[relative]["content"])
        current_blob = git_blob(item.stdout.encode()) if item.returncode == 0 else None
        if current_blob not in (PAYLOAD[relative]["before"], git_blob(desired)):
            raise RuntimeError("The published version of " + relative + " changed. No update files were changed; ask for a fresh installer.")
    write_files(writes)
    return checkout


def ensure_dependencies(root, checkout):
    if (checkout / "node_modules").is_dir():
        return
    if ((root / "node_modules").is_dir()
            and (root / "package-lock.json").read_bytes() == (checkout / "package-lock.json").read_bytes()):
        (checkout / "node_modules").symlink_to(root / "node_modules", target_is_directory=True)
    else:
        run(["npm", "ci", "--no-audit", "--no-fund"], checkout)


def open_pull_request(checkout):
    # Never change an existing PR's merge state or merge main automatically.
    existing = run(["gh", "pr", "list", "--repo", REPOSITORY, "--head", BRANCH, "--base", "main", "--state", "open", "--json", "url"], checkout, capture=True)
    records = json.loads(existing.stdout)
    if records:
        return records[0]["url"]
    body = """Make Android the primary path on the public Delimt website.

Implements the approved dark landing design with a working scrolling/shopping
pause-screen example, personal reasons, installation links, platform details,
and expandable FAQ. Keeps the homepage visible to signed-in visitors.

The separate /download page keeps the published APK, version, size, checksum,
and Accessibility setup guide, using the same navigation and visual style.
Moves the existing pricing and founding-member checkout to /pricing; legacy
/#pricing links still work. Payment amounts, callbacks, and backend logic are
retained. Updates the page title and search/social descriptions.

Validation: 12 existing download/referral checks, production Vite build,
desktop and narrow-screen browser checks, demo switching, FAQ, installation
guide, and pricing navigation. No live payment was made.

This is a website-only update. No APK rebuild, re-upload, release metadata
replacement, database migration, authentication change, or dependency update.
Merge this PR to deploy through the existing Vercel configuration.
"""
    with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", suffix=".md", delete=False) as stream:
        stream.write(body)
        path = Path(stream.name)
    try:
        return run(["gh", "pr", "create", "--repo", REPOSITORY, "--base", "main", "--head", BRANCH,
                    "--title", TITLE, "--body-file", str(path)], checkout, capture=True).stdout.strip()
    finally:
        path.unlink(missing_ok=True)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--prepare-only", action="store_true", help="Write design files into a separate worktree; no account access, commit, or push")
    options = parser.parse_args()
    root = Path(run(["git", "rev-parse", "--show-toplevel"], Path.cwd(), capture=True).stdout.strip()).resolve()
    remote = run(["git", "remote", "get-url", "origin"], root, capture=True).stdout.strip()
    if not re.fullmatch(r"(?:https://github\.com/|git@github\.com:)activist015/delimt(?:\.git)?/?", remote, re.I):
        raise RuntimeError("Run this inside the activist015/delimt Codespace.")
    if not options.prepare_only:
        if not shutil.which("gh"):
            raise RuntimeError("GitHub CLI (gh) is missing from this Codespace.")
        run(["gh", "auth", "status"], root, capture=True)

    print("1/4 Checking main and preparing a separate website branch.", flush=True)
    run(["git", "fetch", "origin", "main"], root)
    if main_has_design(root):
        print("The design is already on main. Nothing needs to be applied again.")
        return
    checkout = prepare_worktree(root)
    if options.prepare_only:
        print("Prepared:", checkout)
        print("No APK, original checkout, or database changes were made.")
        return

    print("2/4 Running the download/referral checks and building the website.", flush=True)
    run(["node", "--test", "tests/android-download.test.js", "tests/profile-referral.test.js"], checkout)
    ensure_dependencies(root, checkout)
    run(["npm", "run", "build"], checkout)
    run(["git", "diff", "--check"], checkout)

    print("3/4 Saving the website changes to GitHub.", flush=True)
    run(["git", "add", "--", *PAYLOAD.keys()], checkout)
    staged = run(["git", "diff", "--cached", "--name-only"], checkout, capture=True).stdout.splitlines()
    if any(path not in PAYLOAD for path in staged):
        raise RuntimeError("Unexpected staged files were preserved. No commit was created.")
    if staged:
        run(["git", "commit", "-m", TITLE], checkout)
    run(["git", "push", "-u", "origin", BRANCH], checkout)

    print("4/4 Opening the website review link.", flush=True)
    pr_url = open_pull_request(checkout)
    print("\nDesign update ready:", pr_url)
    print("Open that link and merge the PR after its checks pass. Vercel will deploy the design.")
    print("The /download guide and current APK stay available. No Android rebuild is needed.")


if __name__ == "__main__":
    try:
        main()
    except (RuntimeError, OSError, ValueError) as error:
        print("\nUpdate paused:", error, file=sys.stderr)
        print("Your original checkout, APK release, and database were preserved.", file=sys.stderr)
        sys.exit(1)
